package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory.TypeBindings;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class TypeFactory__fromClass_TriageGen2Test {

    private TypeFactory _typeFactory;
    private TypeFactory _spyTypeFactory;

    @Before
    public void setUp() {
        _typeFactory = TypeFactory.defaultInstance();
        // Using a spy to access protected methods and mock internal behaviors if necessary
        _spyTypeFactory = Mockito.spy(_typeFactory);
    }

    /**
     * Test Case: Well-known simple type (e.g., String.class)
     * Covers: _findWellKnownSimple returns non-null
     */
    @Test
    public void test_fromClass_wellKnownSimple() throws Exception {
        // String is usually a well-known simple type in Jackson
        JavaType result = accessFromClass(null, String.class, null);
        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    /**
     * Test Case: Cache hit
     * Covers: _typeCache.get(key) returns non-null
     */
    @Test
    public void test_fromClass_cacheHit() throws Exception {
        Class<?> rawType = Integer.class;
        JavaType firstCall = accessFromClass(null, rawType, null);
        JavaType secondCall = accessFromClass(null, rawType, null);

        assertSame("Should return same instance from cache", firstCall, secondCall);
    }

    /**
     * Test Case: Recursive reference (Self-reference)
     * Covers: context.find(rawType) != null -> ResolvedRecursiveType
     */
    @Test
    public void test_fromClass_recursiveReference() throws Exception {
        ClassStack mockContext = mock(ClassStack.class);
        Class<?> rawType = Object.class;

        // Simulate that the type is already in the stack (detecting a cycle)
        when(mockContext.find(rawType)).thenReturn(mock(ClassStack.class));

        JavaType result = accessFromClass(mockContext, rawType, null);

        assertTrue("Should return a recursive type", result instanceof ResolvedRecursiveType);
    }

    /**
     * Test Case: Array Type
     * Covers: rawType.isArray() == true
     */
    @Test
    public void test_fromClass_arrayType() throws Exception {
        Class<?> arrayType = String[].class;
        JavaType result = accessFromClass(null, arrayType, null);

        assertTrue("Result should be an ArrayType", result instanceof ArrayType);
        assertEquals(String.class, ((ArrayType) result).getElementType().getRawClass());
    }

    /**
     * Test Case: Properties class special handling
     * Covers: rawType == Properties.class branch
     */
    @Test
    public void test_fromClass_propertiesSpecialCase() throws Exception {
        JavaType result = accessFromClass(null, Properties.class, null);

        assertNotNull(result);
        assertTrue("Properties should be handled as a MapType", result instanceof MapType);
    }

    /**
     * Test Case: Interface type
     * Covers: rawType.isInterface() == true
     */
    @Test
    public void test_fromClass_interfaceType() throws Exception {
        JavaType result = accessFromClass(null, Map.class, null);

        assertNotNull(result);
        // Map is an interface, it should go through _resolveSuperInterfaces
        assertTrue(result instanceof MapType || result.getRawClass().equals(Map.class));
    }

    /**
     * Test Case: Bindings handling
     * Covers: bindings != null and bindings.isEmpty() == false
     */
    @Test
    public void test_fromClass_withBindings() throws Exception {
        // We use a mock for TypeBindings to control isEmpty() and asKey()
        TypeBindings mockBindings = mock(TypeBindings.class);
        when(mockBindings.isEmpty()).thenReturn(false);
        when(mockBindings.asKey(any())).thenReturn("mockedKey");

        // To trigger the cache/key logic, we'd need to manipulate the internal cache, 
        // but here we just ensure the branch is covered.
        JavaType result = accessFromClass(null, Integer.class, mockBindings);

        assertNotNull(result);
        verify(mockBindings).asKey(Integer.class);
    }

    /**
     * Test Case: Null context initialization
     * Covers: if (context == null) { context = new ClassStack(rawType); }
     */
    @Test
    public void test_fromClass_nullContext() throws Exception {
        // Passing null context should trigger the creation of a new ClassStack
        JavaType result = accessFromClass(null, Double.class, null);
        assertNotNull(result);
    }

    /**
     * Test Case: Complex hierarchy (SuperClass refinement)
     * Covers: superClass != null -> superClass.refine(...)
     */
    @Test
    public void test_fromClass_refinement() throws Exception {
        // Using a class that extends another to trigger refinement logic
        // Since we can't easily mock the internal _resolveSuperClass without heavy mocking,
        // we rely on standard Java classes that have hierarchies.
        JavaType result = accessFromClass(null, java.util.ArrayList.class, null);
        assertNotNull(result);
    }

    /**
     * Helper method to access the protected method _fromClass via reflection
     */
    private JavaType accessFromClass(ClassStack context, Class<?> rawType, TypeBindings bindings) throws Exception {
        java.lang.reflect.Method method = TypeFactory.class.getDeclaredMethod("_fromClass", ClassStack.class, Class.class, TypeBindings.class);
        method.setAccessible(true);
        return (JavaType) method.invoke(_typeFactory, context, rawType, bindings);
    }
}
